from __future__ import annotations
import argparse, json, math, pathlib

_THIS = pathlib.Path(__file__).resolve().parent
_NSC = _THIS.parent
SCENE_DIR = _NSC / "configs" / "env" / "scene"
EXP_DIR = _NSC / "configs" / "experiment"

HEADER = """# @package _global_
# AUTO-GENERATED by build_langv2_eval.py — langv2 LANGUAGE closed-loop eval,
# shard {k}/{n}. Instructions use the CANONICAL pattern (matches training
# lang_pattern), NOT the manifest's random phrasings. success_dist {sd} m.
defaults:
  - override /policy: {policy}
  - override /task: lang
  - override /env/scene: {placeholder}
  - override /env/robot: nova_carter
  - override /env/camera_set: with_4cctv_2x3_bigcam
  - override /env/astar: warehouse_2x3
  - override /controller: omnivla_default
  - override /recorder: default
  - _self_
run: {{name: "{label}{k}", notes: "langv2 closed-loop lang eval, shard {k}/{n}, canonical pattern"}}
control_hz: 3.0
record_hz: 3.0
fine_grained: {{enabled: true, control_hz: 30}}
task: {{max_steps: 120, success_dist: {sd}}}
env:
  cameras:
    cctv_NE: {{logging: false}}
    cctv_NW: {{logging: false}}
    cctv_SE: {{logging: false}}
    cctv_SW: {{logging: false}}
recorder: {{runs_root: "{runs_root}/{label}{k}"}}
runs:
"""


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--manifest", required=True)
    ap.add_argument("--policy", required=True)
    ap.add_argument("--label", required=True, help="exp/run label prefix, e.g. langv2test_eval_p")
    ap.add_argument("--runs-root", required=True)
    ap.add_argument("--per-shard", type=int, default=8)
    ap.add_argument("--success-dist", type=float, default=0.3)
    ap.add_argument("--pattern", default="move toward the {x}")
    args = ap.parse_args()

    scenes = json.loads(pathlib.Path(args.manifest).read_text())["scenes"]
    runs = []
    skipped = []
    for m in scenes:
        name = m["name"]
        if not (SCENE_DIR / f"{name}.yaml").exists():
            skipped.append(name); continue
        instr = args.pattern.format(x=m["target_phrase"])
        runs.append((name, instr))
    if not runs:
        print("[build_langv2_eval] no scenes found — check --manifest / SCENE_DIR")
        return 1

    n_shards = max(1, math.ceil(len(runs) / args.per_shard))
    for k in range(n_shards):
        bucket = runs[k * args.per_shard:(k + 1) * args.per_shard]
        if not bucket:
            continue
        body = "\n".join(
            f'  - {{ name: "{nm}", env_scene: {nm}, '
            f'lang_instruction: "{instr}", action: RELOAD }}'
            for nm, instr in bucket)
        txt = HEADER.format(k=k + 1, n=n_shards, sd=args.success_dist,
                            policy=args.policy, placeholder=bucket[0][0],
                            label=f"{args.label}_p", runs_root=args.runs_root) + body + "\n"
        (EXP_DIR / f"{args.label}_p{k + 1}.yaml").write_text(txt)
        print(f"  {args.label}_p{k + 1}.yaml: {len(bucket)} runs")

    print(f"[build_langv2_eval] {len(runs)} eval runs in {n_shards} shards "
          f"(policy={args.policy}, pattern={args.pattern!r}, success_dist={args.success_dist})")
    if skipped:
        print(f"[build_langv2_eval] SKIPPED {len(skipped)} scenes with no yaml: {skipped[:5]}...")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
